<script setup>
import { ref, watch } from 'vue'; import MButton from '../../../components/mds/MButton.vue'; import MEmptyState from '../../../components/mds/MEmptyState.vue'; import MInput from '../../../components/mds/MInput.vue'; import MTag from '../../../components/mds/MTag.vue'; import { PARTNER_TYPES, partnerTypeMeta } from '../domain/partner-list.mjs';
const props = defineProps({ type:String, rows:{type:Array,default:()=>[]}, total:Number, page:Number, pageSize:Number, search:String, canCreate:Boolean }); const emit=defineEmits(['search','page','open','create','change-type']); const query=ref(props.search||''); watch(()=>props.search,(value)=>{query.value=value||'';}); function submit(){emit('search',query.value.trim());}
</script>
<template><section class="min-h-0 bg-[var(--mds-bg-page)] p-4"><div class="mx-auto max-w-[1200px] space-y-4"><header class="rounded-lg bg-[var(--mds-bg)] px-5 py-4 shadow-[var(--mds-shadow-card)]"><div class="flex flex-wrap items-start justify-between gap-4"><div><h1 class="text-[20px] font-semibold leading-7">{{ partnerTypeMeta(type).label }}</h1><p class="mt-1 text-[13px] text-[var(--mds-text-secondary)]">Danh sách đã được máy chủ projection theo PolicyEngine.</p></div><MButton v-if="canCreate" variant="primary" @click="emit('create')">Thêm cơ quan</MButton></div><div class="mt-4 flex flex-wrap gap-2"><MButton v-for="item in PARTNER_TYPES" :key="item.value" :variant="item.value===type?'primary':'neutral'" @click="emit('change-type',item.value)">{{ item.label }}</MButton></div><form class="mt-4 flex max-w-[560px] gap-2" @submit.prevent="submit"><MInput v-model="query" placeholder="Tìm tên, đơn vị chủ quản, website…"/><MButton variant="primary" @click="submit">Tìm</MButton></form></header><section class="overflow-hidden rounded-lg bg-[var(--mds-bg)] shadow-[var(--mds-shadow-card)]"><div class="flex items-center justify-between border-b border-[var(--mds-border-light)] px-5 py-3"><p class="text-[13px] text-[var(--mds-text-secondary)]">{{ Number(total||0).toLocaleString('vi-VN') }} cơ quan</p><p class="text-[12px] text-[var(--mds-text-secondary)]">Trang {{ page }}</p></div><div v-if="rows.length" class="overflow-x-auto"><table class="w-full min-w-[760px] text-left"><thead class="bg-[var(--mds-bg-page)] text-[12px] font-medium text-[var(--mds-text-secondary)]"><tr><th class="px-5 py-3">Cơ quan</th><th class="px-3 py-3">Thông tin</th><th class="px-3 py-3">Cấp độ</th><th class="px-3 py-3 text-right">Nhân sự</th><th class="px-5 py-3"></th></tr></thead><tbody class="divide-y divide-[var(--mds-border-light)]"><tr v-for="row in rows" :key="row.id" class="hover:bg-[var(--mds-bg-page)]"><td class="px-5 py-3"><strong class="block text-[13px]">{{ row.name }}</strong><span v-if="row.parent!=='—'" class="mt-1 block text-[12px] text-[var(--mds-text-secondary)]">{{ row.parent }}</span></td><td class="px-3 py-3 text-[13px]">{{ row.secondary }}</td><td class="px-3 py-3"><MTag color="neutral">{{ row.tier }}</MTag><MTag v-if="row.feeOverdue" color="danger" class="ml-1">Quá hạn phí</MTag></td><td class="px-3 py-3 text-right text-[13px]">{{ row.peopleCount }}</td><td class="px-5 py-3 text-right"><MButton variant="link" @click="emit('open',row.id)">Mở hồ sơ</MButton></td></tr></tbody></table></div><MEmptyState v-else title="Chưa có cơ quan" description="Thử đổi từ khóa hoặc tạo hồ sơ cơ quan mới."/></section><footer class="flex justify-end gap-2"><MButton variant="neutral" :disabled="page<=1" @click="emit('page',page-1)">Trang trước</MButton><MButton variant="neutral" :disabled="page*pageSize>=total" @click="emit('page',page+1)">Trang sau</MButton></footer></div></section></template>
